const now = new Date();

const today = now.toISOString().split('T')[0];

const arrivals = [];
const departures = [];

for (const item of items) {
  const data = item.json;

  if (data["Reservation Status"] !== "Confirmed") {
    continue;
  }

  if (data["Check-in Date"] === today) {
    arrivals.push({
      reservationId: data["Reservation ID"],
      guest: `${data["Guest First Name"]} ${data["Guest Last Name"]}`,
      property: data["Property"],
      checkIn: data["Check-in Date"],
      checkOut: data["Check-out Date"]
    });
  }

  if (data["Check-out Date"] === today) {
    departures.push({
      reservationId: data["Reservation ID"],
      guest: `${data["Guest First Name"]} ${data["Guest Last Name"]}`,
      property: data["Property"],
      checkIn: data["Check-in Date"],
      checkOut: data["Check-out Date"]
    });
  }
}

return [
  {
    json: {
      reportDate: today,
      arrivalCount: arrivals.length,
      departureCount: departures.length,
      arrivals,
      departures
    }
  }
];
